34	func (m detailModel) view() string {
35		var b strings.Builder
36		b.WriteString(m.styles.render(m.styles.appTitle, "SESSION DETAIL"))
37		b.WriteString("\n\n")
38		b.WriteString(m.viewport.View())
39		b.WriteString("\n\n")
40	
41		if m.status != "" {
42			style := m.styles.chipActive
43			if strings.HasPrefix(m.status, "Error:") {
44				style = m.styles.errorText
45			}
46			b.WriteString(m.styles.render(style, m.status))
47			b.WriteString("  ")
48		}
49	
50		help := "j/k scroll  esc back  q quit"
51		if m.canGenerate {
52			help = "j/k scroll  g generate  esc back  q quit"
