133	func (m detailModel) renderSummary() string {
134		if !m.row.HasSummary {
135			return m.styles.render(m.styles.emptyState, "  No summary cached")
136		}
137	
138		var b strings.Builder
139		m.writeField(&b, "Intent", fallback(m.row.Intent, "—"))
140		m.writeField(&b, "Outcome", fallback(m.row.Outcome, "—"))
141		b.WriteString("\n")
142	
143		b.WriteString(m.styles.render(m.styles.detailLabel, "Friction"))
144		b.WriteString("\n")
145		if len(m.row.Friction) == 0 {
146			m.writeEmptyState(&b, "No friction recorded")
147		} else {
148			for _, item := range m.row.Friction {
149				m.writeBullet(&b, item)
150			}
151		}
152	
153		b.WriteString("\n")
154		b.WriteString(m.styles.render(m.styles.detailLabel, "Learnings"))
155		b.WriteString("\n")
156		if len(m.row.Learnings) == 0 {
157			m.writeEmptyState(&b, "No learnings recorded")
158		} else {
159			for _, item := range m.row.Learnings {
160				if item.Path != "" {
161					m.writeBullet(&b, fmt.Sprintf("[%s] %s (%s)", item.Scope, item.Finding, item.Path))
162					continue
163				}
164				m.writeBullet(&b, fmt.Sprintf("[%s] %s", item.Scope, item.Finding))
165			}
166		}
167		return strings.TrimRight(b.String(), "\n")
168	}
